const data = $json.data?.results || $json.data || [];
if (data.length === 0) return [{ empty: true }];

// Filter subscribers that haven't received nurture sequences
return data.slice(0, 50).map(sub => ({
  subscriberId: sub.id,
  email: sub.email,
  name: sub.attribs?.name || sub.name || sub.email?.split('@')[0],
  website: sub.attribs?.website || '',
  niche: sub.attribs?.niche || 'local_business',
  status: 'pending_nurture'
}));

const campaignId = $json.data?.id || $json.id;
if (!campaignId) return [{ error: 'No campaign ID' }];

return [{
  campaignId,
  status: 'campaign_created',
  scheduledAt: new Date().toISOString()
}];
